def process_data(data):
    def process_tuple(t):
        if isinstance(t, tuple):
            return tuple(process_data(item) if isinstance(item, (list, tuple)) else item for item in t)
        return t

    def process_list(l):
        return [process_data(item) for item in l if isinstance(item, (list, tuple))]

    if not data:
        return []

    if isinstance(data, (list, tuple)):
        if isinstance(data[0], (list, tuple)):
            return process_tuple(data)
        else:
            return process_list(data)
    else:
        return process_data(data)
